export interface FurbyFirmwareComponentShape {
  cpu_a: number;
  cpu_x: number;
  cpu_y: number;
  bank: number;
}
export class FurbyFirmwareComponent implements FurbyFirmwareComponentShape {
  cpu_a: number;
  cpu_x: number;
  cpu_y: number;
  bank: number;
  
  constructor(cpu_a: number, cpu_x: number, cpu_y: number, bank: number) {
    this.cpu_a = cpu_a;
    this.cpu_x = cpu_x;
    this.cpu_y = cpu_y;
    this.bank = bank;
  }
}


export interface FurbyDebugComponentShape {
  last_trace_tick: number;
  last_pc: number;
}
export class FurbyDebugComponent implements FurbyDebugComponentShape {
  last_trace_tick: number;
  last_pc: number;
  
  constructor(last_trace_tick: number, last_pc: number) {
    this.last_trace_tick = last_trace_tick;
    this.last_pc = last_pc;
  }
}

